-- SIMULAÇÃO: aplica, confere e desfaz (nada é gravado)
-- Clube: Seu Clube de Poker (7262a52c-c249-4ada-9359-cf6ae33aa1e7). Dados 100% fictícios.
-- Gerado por scripts/demo/gerar-clube-demo.mjs para o dia 2026-11-24 (horário de Brasília).
-- Conteúdo: 36 jogadores, 23 noites (terça, quinta e sábado), 32 mesas,
--           1087 lançamentos, 9 torneios, 23 fechamentos de caixa,
--           10 jogadores com fiado em aberto, e a noite de hoje pronta para gravar.
-- Não toca em nenhum outro clube: tudo usa v_club, e a proteção abaixo confere id e nome.
-- O resultado esperado é um ERRO que começa com "SIMULACAO (nada foi gravado)" e traz as contagens.

do $$
declare
  v_club constant uuid := '7262a52c-c249-4ada-9359-cf6ae33aa1e7';
  v_msg text;
  v_saldo numeric;
  v_ruins int;
begin
  -- Proteção: só roda no clube de demonstração, e só se ele estiver vazio
  if not exists (select 1 from public.clubs where id = v_club and name = 'Seu Clube de Poker') then
    raise exception 'Clube de demonstração não encontrado (id % / nome Seu Clube de Poker). Nada foi feito.', v_club;
  end if;
  if exists (select 1 from public.tables where club_id = v_club)
     or exists (select 1 from public.players where club_id = v_club)
     or exists (select 1 from public.tournaments where club_id = v_club) then
    raise exception 'O clube de demonstração já tem dados. Rode antes o clube_demonstracao_remover.sql. Nada foi feito.';
  end if;

  -- Configuração do clube
  update public.clubs set beer_price = 8, energy_price = 12, marketing_club_name = 'Seu Clube de Poker' where id = v_club;
  update public.club_settings set custom_products = '[{"id":"p1","name":"Cerveja","category":"Bebidas","price":8,"active":true},{"id":"p2","name":"Long neck","category":"Bebidas","price":12,"active":true},{"id":"p3","name":"Refrigerante","category":"Bebidas","price":6,"active":true},{"id":"p4","name":"Água","category":"Bebidas","price":4,"active":true},{"id":"p5","name":"Energético","category":"Bebidas","price":12,"active":true},{"id":"p6","name":"Porção de fritas","category":"Comida","price":30,"active":true},{"id":"p7","name":"Hambúrguer","category":"Comida","price":28,"active":true}]'::jsonb, default_buyin = 200, default_rebuy = 200,
    business_days = array['terca','quinta','sabado'], opening_time = '20:00', closing_time = '05:00', marketing_club_name = 'Seu Clube de Poker'
    where club_id = v_club;

  -- Jogadores (nomes inventados; telefones com DDD 00, que não existe)

  -- Mesas de cash (31 mesas em 23 noites)
  update public.tables set status = 'closed', closed_at = '2026-10-02T07:40:00.000Z'::timestamptz where id = 'c71d73c9-ea1d-4a15-ba67-6e7c34c2553d';
  update public.tables set status = 'closed', closed_at = '2026-10-02T06:38:00.000Z'::timestamptz where id = 'f5513a73-ae27-4823-b929-0b3563ec74bf';
  update public.tables set status = 'closed', closed_at = '2026-10-04T07:40:00.000Z'::timestamptz where id = '15b7f714-074b-4bba-844d-8181c31a850b';
  update public.tables set status = 'closed', closed_at = '2026-10-07T07:35:00.000Z'::timestamptz where id = 'aaf2a4d7-eb24-43c0-a8e3-ff2beb681be7';
  update public.tables set status = 'closed', closed_at = '2026-10-09T06:47:00.000Z'::timestamptz where id = 'f6d10506-f837-41bf-9629-a3b4ba9168c1';
  update public.tables set status = 'closed', closed_at = '2026-10-09T07:40:00.000Z'::timestamptz where id = '6d728f3d-9c7f-43da-a643-737da3ce2a90';
  update public.tables set status = 'closed', closed_at = '2026-10-11T07:51:00.000Z'::timestamptz where id = '6adf6b65-6ddc-480e-bde6-3047218ac26f';
  update public.tables set status = 'closed', closed_at = '2026-10-14T06:49:00.000Z'::timestamptz where id = '996d8835-58e6-4476-9794-989c4cd684ed';
  update public.tables set status = 'closed', closed_at = '2026-10-16T07:09:00.000Z'::timestamptz where id = '290c89c3-efcb-4d93-8bb7-a37d3bfc5aa9';
  update public.tables set status = 'closed', closed_at = '2026-10-16T07:12:00.000Z'::timestamptz where id = 'f08650a7-695c-42b4-9a5e-a89e620792ea';
  update public.tables set status = 'closed', closed_at = '2026-10-18T07:31:00.000Z'::timestamptz where id = '963ffbe3-a363-43c2-a3dd-ad303c48d131';
  update public.tables set status = 'closed', closed_at = '2026-10-21T07:02:00.000Z'::timestamptz where id = 'cdec6d07-f28b-49be-b2f1-eacfb4071459';
  update public.tables set status = 'closed', closed_at = '2026-10-23T07:09:00.000Z'::timestamptz where id = '099ffdb1-43c1-4dd1-bdd6-bd6bdf19c9f3';
  update public.tables set status = 'closed', closed_at = '2026-10-23T07:18:00.000Z'::timestamptz where id = '843b66f0-1e8d-4d06-b01a-e0fb76a512ea';
  update public.tables set status = 'closed', closed_at = '2026-10-25T07:42:00.000Z'::timestamptz where id = 'fdcfd6a1-8eba-4f8f-9a48-e490f1d84b29';
  update public.tables set status = 'closed', closed_at = '2026-10-28T07:34:00.000Z'::timestamptz where id = '57b86a45-7b86-49cd-bf04-5c617c52401e';
  update public.tables set status = 'closed', closed_at = '2026-10-30T07:04:00.000Z'::timestamptz where id = '60ef539c-78f4-469c-a1f6-fac3d60ecb36';
  update public.tables set status = 'closed', closed_at = '2026-10-30T07:35:00.000Z'::timestamptz where id = '3f5563bb-94e4-4271-a97b-5a278506c457';
  update public.tables set status = 'closed', closed_at = '2026-11-01T06:40:00.000Z'::timestamptz where id = 'a9fe65a3-4722-47d9-82b0-5203d4571f41';
  update public.tables set status = 'closed', closed_at = '2026-11-04T07:24:00.000Z'::timestamptz where id = '66c31b0c-746b-4c6d-ab27-8bb9325f57f5';
  update public.tables set status = 'closed', closed_at = '2026-11-06T07:18:00.000Z'::timestamptz where id = 'ffde9300-3709-4b9b-bb7f-f7663bc3b82c';
  update public.tables set status = 'closed', closed_at = '2026-11-06T07:18:00.000Z'::timestamptz where id = 'e6a479a5-297e-4fe7-8198-0f132e315456';
  update public.tables set status = 'closed', closed_at = '2026-11-08T05:56:00.000Z'::timestamptz where id = '69b1e21f-7883-4b28-a9b2-15a9a182b1b9';
  update public.tables set status = 'closed', closed_at = '2026-11-11T07:07:00.000Z'::timestamptz where id = 'ceef79d2-83dc-4c30-b07a-1a47f244972d';
  update public.tables set status = 'closed', closed_at = '2026-11-13T07:23:00.000Z'::timestamptz where id = '9942b550-f0ee-4f2a-b5da-e4efc5c86cd9';
  update public.tables set status = 'closed', closed_at = '2026-11-13T06:52:00.000Z'::timestamptz where id = 'ee91a650-7a77-4e36-8cd1-0128dbdb0ea9';
  update public.tables set status = 'closed', closed_at = '2026-11-15T05:57:00.000Z'::timestamptz where id = '77b2d73e-48b1-4148-8419-cdfacdc89e27';
  update public.tables set status = 'closed', closed_at = '2026-11-18T06:56:00.000Z'::timestamptz where id = 'f1c9b839-0e5a-43c1-967b-c5c0b81aa44a';
  update public.tables set status = 'closed', closed_at = '2026-11-20T06:31:00.000Z'::timestamptz where id = '4eab6512-3a87-4329-966d-7c22f5999cbd';
  update public.tables set status = 'closed', closed_at = '2026-11-20T07:21:00.000Z'::timestamptz where id = 'd0c00d79-5b0c-4bd4-9671-a3db08aa2b12';
  update public.tables set status = 'closed', closed_at = '2026-11-22T06:47:00.000Z'::timestamptz where id = '6a509546-f32a-4059-a270-d4d4ae397185';

  -- Pagamentos de fiado (PIX/dinheiro) feitos em noites seguintes

  -- Torneios encerrados (8)

  -- Fechamentos de caixa (esperado calculado pelo próprio sistema)

  -- Noite de hoje, para gravar ao vivo: mesa aberta e torneio com inscritos

  -- O histórico da mesa registra "jogador entrou" com a hora da gravação; usa a hora em que ele entrou
  update public.table_events e set created_at = tp.created_at
    from public.table_players tp
    where e.club_id = v_club and e.event_type = 'jogador_entrou' and e.ref_id = tp.id;

  -- Conferências
  select count(*) into v_ruins from public.cash_closings where club_id = v_club and abs(difference) > 10;
  if v_ruins > 0 then raise exception 'Conferência falhou: fechamento com diferença inesperada.'; end if;
  select coalesce(sum(saldo), 0) into v_saldo from public.fiado_saldos where club_id = v_club and saldo > 0;
  if v_saldo <> 1225 then raise exception 'Conferência falhou: fiado em aberto % (esperado 1225).', v_saldo; end if;
  if exists (select 1 from public.fiado_saldos where club_id = v_club and saldo < 0) then
    raise exception 'Conferência falhou: saldo de fiado negativo.';
  end if;
  if (select count(*) from public.tables where club_id = v_club and status = 'active') <> 1 then
    raise exception 'Conferência falhou: deveria haver só a mesa de hoje aberta.';
  end if;

  select format('jogadores %s | mesas %s | lançamentos %s | torneios %s | fechamentos %s | fiado em aberto R$ %s | eventos de mesa %s',
    (select count(*) from public.players where club_id = v_club),
    (select count(*) from public.tables where club_id = v_club),
    (select count(*) from public.transactions where club_id = v_club),
    (select count(*) from public.tournaments where club_id = v_club),
    (select count(*) from public.cash_closings where club_id = v_club),
    v_saldo,
    (select count(*) from public.table_events where club_id = v_club))
  into v_msg;
  raise exception 'SIMULACAO (nada foi gravado): tudo certo. %', v_msg;
end
$$;
